import { createElement, useEffect, useState } from 'react'
import SvgIcon from '@mui/material/SvgIcon'

type El = string | [string, Record<string, string>]
let data: Record<string, El[]> | null = null
let promise: Promise<void> | null = null
const subs = new Set<() => void>()

/** Icon paths are plain data (generated by scripts/gen-icons.mjs) and load once, on first use. */
export function loadIcons() {
  promise ??= import('./icons-data.json').then((m) => {
    data = m.default as unknown as Record<string, El[]>
    subs.forEach((f) => f())
  })
  return promise
}
export function useIconData() {
  const [, force] = useState(0)
  useEffect(() => {
    if (data) return
    const f = () => force((x) => x + 1)
    subs.add(f)
    loadIcons()
    return () => { subs.delete(f) }
  }, [])
  return data
}

export const ICON_STYLES = ['Filled', 'Outlined', 'Rounded', 'Sharp', 'TwoTone'] as const
export const iconStyleOf = (file: string) => ICON_STYLES.find((s) => s !== 'Filled' && file.endsWith(s)) ?? 'Filled'
export const iconLabel = (file: string) => file.replace(/(Outlined|Rounded|Sharp|TwoTone)$/, '')

export function Icon({ name, sx }: { name: string; sx?: Record<string, unknown> }) {
  const d = useIconData()
  const els = d?.[name]
  return (
    <SvgIcon sx={sx as never}>
      {els?.map((e, i) =>
        typeof e === 'string'
          ? <path key={i} d={e} />
          : e[0] === 'path' || e[0] === 'circle' || e[0] === 'ellipse' ? createElement(e[0], { ...e[1], key: i }) : null,
      )}
    </SvgIcon>
  )
}
